Method.Implementation:
    #dim stream
    #dim tSC As %Status=$$$OK
    try{
	    $$$TRACE("Inside the ProcessMergeRequest")
		set stream=..CreateXmlStreamFromObject(pRequest)
		set tSC=..ProcessXmlMessage(stream,.pResponse)
		if ($$$ISOK(tSC)){
	   	   set tSC=..ProcessDrFirstHttpResponse(pResponse,"MERGE")
	    }
	 }catch e{ Set tSC = e.AsStatus()
	 		   Set tSC =  ##class(IHC.ITF.ITFCOMMON.Utility).ProcessError(e.AsStatus())

			}

    quit tSC

	#dim stream
	#dim tSC As %Status=$$$OK
    try{
	   $$$TRACE("Inside the ProcessAddUpdateRequest")
	   set stream=..CreateXmlStreamFromObject(pRequest)
	   set tSC=..ProcessXmlMessage(stream,.pResponse)
	   if ($$$ISOK(tSC)){
	      set tSC=..ProcessDrFirstHttpResponse(pResponse,"ADDUPDATE")
	   }
	}catch e{Set tSC = e.AsStatus()
	 		   Set tSC =  ##class(IHC.ITF.ITFCOMMON.Utility).ProcessError(e.AsStatus())

			}   
	quit tSC


  #dim tSC As %Status=$$$OK 
  #dim statusLine As %String=""
  #dim statusCode As %String
  #dim statusDesc As %String
  #dim errorCode As %String
  #dim errorDesc,patStatus As %String
  #dim statusLineKey As %String="StatusLine"
  #dim mergeResponse As IHC.ITF.Response.DrFirst.Merge.RCExtResponse
  #dim addUpdateResponse As IHC.ITF.Response.DrFirst.AddUpdate.RCExtResponse

  // 
  do {
	  $$$TRACE("Inside the ProcessDrFirstHttpResponse.. "_responseType)
	  set statusLine=httpResponse.HTTPHeaders.GetAt(statusLineKey)
	  if (statusLine'=""){
		  set statusCode=$piece(statusLine," ",2)
		  set statusDesc=$piece(statusLine," ",3)
	  }
	  $$$TRACE("StatusCode "_statusCode_" statusDesc "_statusDesc)
	  // If status code is 200 the check the reponse to see if it got processed correctly or not
  	  if (statusCode="200"){
	  	  If (responseType="ADDUPDATE"){
		  	  set addUpdateResponse=##class(IHC.ITF.Response.DrFirst.AddUpdate.RCExtResponse).%New()
		  	  set tSC=..CreateObjectFromXMLStream(httpResponse.Stream,.addUpdateResponse)
		  	  if $$$ISOK(tSC){
			  	  $$$TRACE("Add Update Response Status "_addUpdateResponse.Response.Status.content)
			  	  if ($ZCONVERT(addUpdateResponse.Response.Status.content,"L")="error"){
				  	  set tSC=$$$ERROR(addUpdateResponse.Response.Error.Code.content,addUpdateResponse.Response.Error.Text.content)
				  	  quit
			  	  }else{
				  	  #dim patient As IHC.ITF.Response.DrFirst.AddUpdate.Patient
				  	  $$$TRACE("Check Add Update Response Patient List Status ")
			  	   	  if (($ISOBJECT(addUpdateResponse.Response.PatientList))&&(addUpdateResponse.Response.PatientList.Patient.Count()>0)){
					  	  set key=""
					  	  set patient=addUpdateResponse.Response.PatientList.Patient.GetNext(.key)
					  	  if ((key'="") && $ISOBJECT(patient)){
						  	  $$$TRACE("Add Update Response Patient List Status "_patient.Status.content)
						  	  set patStatus=$ZCONVERT(patient.Status.content,"L")
					  	 	 if ((patStatus'="updated")&&(patStatus'="created")){
					  	  		set tSC=$$$ERROR(patient.Error.Code.content,patient.Error.Text.content)
				  	  	  		quit
					  	 	 }
					  	  }
				  	  }
			  	  }
			  }

		  }elseif (responseType="MERGE"){
			  set mergeResponse=##class(IHC.ITF.Response.DrFirst.Merge.RCExtResponse).%New()
		  	  set tSC=..CreateObjectFromXMLStream(httpResponse.Stream,.mergeResponse)
		  	  if $$$ISOK(tSC){
			  	  $$$TRACE("Merge Response Status "_mergeResponse.Response.Status.content)
			  	  if ($ZCONVERT(mergeResponse.Response.Status.content,"L")="error"){
				  	  set tSC=$$$ERROR(mergeResponse.Response.Error.Code.content,mergeResponse.Response.Error.Text.content)
				  	  quit
			  	  }
		  	  }
		  }

	  }else {
		 set tSC=$$$ERROR("HTTP"_statusCode,statusDesc)
	 }


  }while(0)


  quit tSC

#dim tSC As %Status=$$$OK #dim xmlString #dim xmlReader As %XML.Reader #dim objXMLStream As %GlobalCharacterStream $$$TRACE("Inside CreateObjectFromXMLStream") do { if (className="")&&($ISOBJECT(object)){ set className=object.%ClassName(1) }
set resolver=##class(%XML.SAX.NullEntityResolver).%New() set xmlReader = ##class(%XML.Reader).%New() set xmlReader.EntityResolver=resolver if ($ISOBJECT(xmlStream)){ do xmlStream.Rewind()
set objXMLStream=##class(%GlobalCharacterStream).%New() while ('xmlStream.AtEnd) { do objXMLStream.Write(xmlStream.Read()) } do objXMLStream.Rewind() set tSC=xmlReader.OpenStream(objXMLStream) set classShortName=$PIECE(className,".",$LENGTH(className,".")) do xmlReader.Correlate(classShortName,className) do xmlReader.Next(.object,.status)
} } while(0) quit tSC
